//
//  VocabularyImportExportService.swift
//  SwiftMandarin
//
//  Service for importing and exporting vocabulary data with duplicate detection
//

import Foundation
import SwiftUI
import UniformTypeIdentifiers
#if os(macOS)
import AppKit
#else
import UIKit
#endif

// MARK: - Export Format

enum VocabularyExportFormat: String, CaseIterable, Identifiable {
    case json = "JSON"
    case csv = "CSV"

    var id: String { rawValue }

    var fileExtension: String {
        switch self {
        case .json: return "json"
        case .csv: return "csv"
        }
    }

    var mimeType: String {
        switch self {
        case .json: return "application/json"
        case .csv: return "text/csv"
        }
    }
}

// MARK: - Import Result

struct ImportResult {
    let imported: Int
    let skipped: Int
    let errors: [String]
    /// AI word-analyses restored into the explanation cache during this import.
    var explanationsRestored: Int = 0

    var summary: String {
        var parts: [String] = []
        if imported > 0 {
            parts.append("\(imported) word\(imported == 1 ? "" : "s") imported")
        }
        if skipped > 0 {
            parts.append("\(skipped) duplicate\(skipped == 1 ? "" : "s") skipped")
        }
        if explanationsRestored > 0 {
            parts.append("\(explanationsRestored) AI analys\(explanationsRestored == 1 ? "is" : "es") restored")
        }
        var summary = parts.joined(separator: ", ")
        if summary.isEmpty { summary = "Nothing to import" }
        if !errors.isEmpty {
            summary += ". Errors: \(errors.count)"
        }
        return summary
    }
}

