    var body: some View {
        VStack(spacing: 0) {
            // Header with word count and icon
            HStack(spacing: 16) {
                Image(systemName: "square.and.arrow.up.circle.fill")
                    .font(.system(size: 44))
                    .foregroundStyle(.blue)

                VStack(alignment: .leading, spacing: 2) {
                    Text("Export Vocabulary")
                        .font(.headline)
                    Text("\(terms.count) word\(terms.count == 1 ? "" : "s") ready to export")
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }

                Spacer()

                Button {
                    dismiss()
                } label: {
                    Image(systemName: "xmark.circle.fill")
                        .font(.title2)
                        .foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
            }
            .padding()
            .background(.quaternary.opacity(0.3))

            Divider()

            // Content
            Form {
                // Format Selection with visual cards
                Section {
                    HStack(spacing: 12) {
                        ForEach(VocabularyExportFormat.allCases) { format in
                            FormatCard(
                                format: format,
                                isSelected: exportFormat == format
