import Foundation

// --- Replicate splitCSVRecords (quote-aware) ---
func splitCSVRecords(_ content: String) -> [String] {
    var records: [String] = []; var current = ""; var inQuotes = false
    let chars = Array(content); var i = 0
    while i < chars.count {
        let c = chars[i]
        if c == "\"" {
            if inQuotes, i + 1 < chars.count, chars[i+1] == "\"" { current.append("\""); current.append("\""); i += 2; continue }
            inQuotes.toggle(); current.append(c)
        } else if (c == "\n" || c == "\r"), !inQuotes {
            if c == "\r", i + 1 < chars.count, chars[i+1] == "\n" { i += 1 }
            records.append(current); current = ""
        } else { current.append(c) }
        i += 1
    }
    if !current.isEmpty { records.append(current) }
    return records
}
func parseCSVLine(_ line: String) -> [String] {
    var columns: [String] = []; var current = ""; var inQuotes = false
    let chars = Array(line); var i = 0
    while i < chars.count {
        let char = chars[i]
        if char == "\"" {
            if inQuotes && i + 1 < chars.count && chars[i+1] == "\"" { current.append("\""); i += 1 }
            else { inQuotes.toggle() }
        } else if char == "," && !inQuotes { columns.append(current); current = "" }
        else { current.append(char) }
        i += 1
    }
    columns.append(current); return columns
}
func escapeCSV(_ value: String) -> String {
    let e = value.replacingOccurrences(of: "\"", with: "\"\"")
    return (e.contains(",") || e.contains("\n") || e.contains("\"")) ? "\"\(e)\"" : e
}

// TEST 1: multi-line quoted field round-trips (the bug Fix B addresses)
let multiline = "学习\nline2"
let row = "\(escapeCSV("好")),\(escapeCSV(multiline)),\(escapeCSV("normal"))"
let csv = "H1,H2,H3\n" + row + "\n好2,def2,pos2\n"
let recs = splitCSVRecords(csv)
assert(recs.count == 3, "expected 3 records (header + 2 rows), got \(recs.count): \(recs)")
let cols0 = parseCSVLine(recs[1])
assert(cols0.count == 3, "row1 should have 3 cols, got \(cols0.count): \(cols0)")
assert(cols0[1] == multiline, "multiline field corrupted: \(cols0[1].debugDescription)")
let cols1 = parseCSVLine(recs[2])
assert(cols1[0] == "好2" && cols1.count == 3, "row2 wrong: \(cols1)")
print("TEST 1 PASS: multi-line quoted field round-trips; rows not split mid-quote")

// TEST 2: CRLF handled
let crlf = "A,B\r\n1,2\r\n"
let r2 = splitCSVRecords(crlf)
assert(r2.count == 2, "CRLF: expected 2, got \(r2.count): \(r2)")
assert(parseCSVLine(r2[1]) == ["1","2"], "CRLF row wrong")
print("TEST 2 PASS: CRLF treated as single boundary")

// TEST 3: base64(compact JSON) round-trip for AI Data column
struct Mini: Codable, Equatable { let word: String; let date: Date }
let enc = JSONEncoder(); enc.dateEncodingStrategy = .iso8601
let dec = JSONDecoder(); dec.dateDecodingStrategy = .iso8601
let original = [Mini(word: "学习", date: Date(timeIntervalSince1970: 1_700_000_000))]
let b64 = (try! enc.encode(original)).base64EncodedString()
// no raw newlines in base64 -> survives CSV cell
assert(!b64.contains("\n") && !b64.contains(","), "base64 must be CSV-safe")
let aiCell = escapeCSV(b64)  // should be unchanged (no special chars)
let decoded = try! dec.decode([Mini].self, from: Data(base64Encoded: aiCell)!)
assert(decoded == original, "AI Data round-trip failed")
print("TEST 3 PASS: base64(compact JSON) AI-data round-trips and is CSV-safe")

// TEST 4: envelope vs legacy array disambiguation
struct Envelope: Codable { var schemaVersion = 2; var n: Int }
struct Term: Codable, Equatable { let chinese: String }
let envData = try! enc.encode(Envelope(n: 5))
let arrData = try! enc.encode([Term(chinese: "好")])
// decode array as envelope -> fails; decode envelope as array -> fails
assert((try? dec.decode([Term].self, from: envData)) == nil, "envelope wrongly decoded as array")
assert((try? dec.decode(Envelope.self, from: arrData)) == nil, "array wrongly decoded as envelope")
assert((try? dec.decode([Term].self, from: arrData)) == [Term(chinese: "好")], "legacy array decode failed")
print("TEST 4 PASS: envelope/legacy-array disambiguation is unambiguous")

print("\nALL CSV/JSON ROUND-TRIP TESTS PASSED")
